 public struct Ring:Sendable {
  public var glyph:Glyph
  public var diameter:Double
  public var font:Double{diameter/glyph.diameter*100}
  public var stroke:Double{glyph.stroke*font/100}
  public var centerFromTop:Double{glyph.centerY*font/100}
 }
 public struct Pair:Sendable {
  public var outer:Ring
  public var inner:Ring
