 }
 public func pair(size:Double,weight:Font.Weight)->Pair {
  let index=Glyph.weights.firstIndex(of:weight) ?? 3
  let sorted=profiles.sorted{$0.size<$1.size}
  let lo=sorted.last(where:{$0.size<=size}) ?? sorted[0]
  let hi=sorted.first(where:{$0.size>=size}) ?? sorted.last!
  let t=hi.size==lo.size ? 0:(size-lo.size)/(hi.size-lo.size)
  let excess=size>hi.size ? size/hi.size:1
  func mix(_ a:Double,_ b:Double)->Double{(a+(b-a)*t)*excess}
  let outer=mix(lo.outerDiameter,hi.outerDiameter)
  let inner=mix(lo.innerDiameter,hi.innerDiameter)
  let target=mix(lo.strokes[index],hi.strokes[index])
  var selected:Pair?;var best=Double.infinity
  for a in glyphs {for b in glyphs {
   let outerRing=Ring(glyph:a,diameter:outer)
   // Keep 1.5 points of negative space at menu-bar sizes, including heavy weights.
   // Native glyph selection may vary the inner diameter instead of closing this gap.
   let minimumGap=1.5*max(0,min(1,(32-size)/10))
   let innerDiameter=min(inner,outer-2*(outerRing.stroke+minimumGap))
   let pair=Pair(outer:outerRing,inner:Ring(glyph:b,diameter:innerDiameter))
   let mismatch=pair.outer.stroke-pair.inner.stroke
   let error=pair.stroke-target
   let cost=20*mismatch*mismatch+2*error*error+0.06*pow(inner-pair.inner.diameter,2)
   if cost<best {best=cost;selected=pair}
  }}
  return selected!
 }
