private struct SymbolMotionDurationKey:EnvironmentKey {
 static let defaultValue:Double=0.3
}
private struct SymbolInspectionScaleKey:EnvironmentKey {
 static let defaultValue:CGFloat=1
}
private struct GaugeCalibrationKey:EnvironmentKey {
 static let defaultValue=GaugeCalibration.standard
}
public extension EnvironmentValues {
 var symbolMotionDuration:Double {
  get{self[SymbolMotionDurationKey.self]}
  set{self[SymbolMotionDurationKey.self]=newValue}
 }
 var symbolInspectionScale:CGFloat {
  get{self[SymbolInspectionScaleKey.self]}
  set{self[SymbolInspectionScaleKey.self]=newValue}
 }
 var gaugeCalibration:GaugeCalibration {
  get{self[GaugeCalibrationKey.self]}
  set{self[GaugeCalibrationKey.self]=newValue}
 }
}
/// Align the actual circle center, rather than the asymmetric open-gauge image box.
struct NativeGaugePlacement:Layout {
 var size:CGFloat
 var center:CGPoint
 var centerFromTop:CGFloat
 func sizeThatFits(proposal:ProposedViewSize,subviews:Subviews,cache:inout ())->CGSize{CGSize(width:size,height:size)}
 func placeSubviews(in bounds:CGRect,proposal:ProposedViewSize,subviews:Subviews,cache:inout ()){
  for view in subviews {
   let dimensions=view.sizeThatFits(.unspecified)
   view.place(at:CGPoint(x:bounds.minX+center.x-dimensions.width/2,y:bounds.minY+center.y-centerFromTop),anchor:.topLeading,proposal:.unspecified)
  }
 }
}
/// Interpolate the native variable input; SF Symbols still draws every frame and endpoint.
/// Image's variableValue initializer does not itself interpolate under a SwiftUI transaction.
@available(macOS 26.0, *)
struct NativeVariableGaugeImage:View,Animatable {
 nonisolated var value:Double
 nonisolated var animatableData:Double {
  get{value}
  set{value=newValue}
 }
 var body:some View {
  Image("compute.gauge.open",variableValue:min(1,max(0,value)))
   .symbolVariableValueMode(.draw)
 }
}
