@available(macOS 26.0, *)
struct NativeGaugeLayer:View {
 var value:Double?
 var spec:GaugeCalibration.Ring
 var size:CGFloat
 var center:CGPoint
 @Environment(\.accessibilityReduceMotion) private var reduceMotion
 @Environment(\.symbolMotionDuration) private var motionDuration
 private var fullNativeGauge:some View {
  NativeGaugePlacement(size:size,center:center,centerFromTop:spec.centerFromTop){
   NativeVariableGaugeImage(value:1)
    .font(.system(size:spec.font,weight:spec.glyph.fontWeight))
    .imageScale(spec.glyph.imageScale).symbolRenderingMode(.monochrome)
  }
 }
 var body:some View {
  if let value,value.isFinite {
   NativeGaugePlacement(size:size,center:center,centerFromTop:spec.centerFromTop){
    ZStack {
     // A native full-value underlay gives the unfilled track enough contrast to
     // distinguish it from whitespace at menu-bar size without changing progress.
     NativeVariableGaugeImage(value:1).symbolRenderingMode(.monochrome).opacity(0.20)
     NativeVariableGaugeImage(value:value).symbolRenderingMode(.hierarchical)
      .animation(reduceMotion ? nil:.smooth(duration:motionDuration),value:value)
    }.font(.system(size:spec.font,weight:spec.glyph.fontWeight)).imageScale(spec.glyph.imageScale)
   }
  }else{
   let dashed=DashedGaugeMetrics.spec(for:spec)
   NativeGaugePlacement(size:size,center:center,centerFromTop:dashed.centerFromTop){
    Image(systemName:"circle.dashed")
     .font(.system(size:dashed.font,weight:dashed.glyph.fontWeight)).imageScale(dashed.glyph.imageScale)
   }.mask{fullNativeGauge.foregroundStyle(.white)}.opacity(0.62)
  }
 }
}
@available(macOS 26.0, *)
public struct NativeGaugePair:View {
 public var weekly:Double?
 public var fiveHour:Double?
 public var size:CGFloat
 public var weight:Font.Weight
 @Environment(\.gaugeCalibration) private var calibration
 @Environment(\.symbolInspectionScale) private var inspectionScale
 public init(weekly:Double?,fiveHour:Double?,size:CGFloat=22,weight:Font.Weight = .regular){self.weekly=weekly;self.fiveHour=fiveHour;self.size=size;self.weight=weight}
 public var body:some View {
  let pair=calibration.pair(size:size,weight:weight)
  let center=CGPoint(x:size/2*inspectionScale,y:size*0.5*inspectionScale)
  let outer=GaugeCalibration.Ring(glyph:pair.outer.glyph,diameter:pair.outer.diameter*inspectionScale)
  let inner=GaugeCalibration.Ring(glyph:pair.inner.glyph,diameter:pair.inner.diameter*inspectionScale)
  ZStack{
   NativeGaugeLayer(value:weekly,spec:outer,size:size*inspectionScale,center:center)
   NativeGaugeLayer(value:fiveHour,spec:inner,size:size*inspectionScale,center:center)
  }.frame(width:size*inspectionScale,height:size*inspectionScale)
 }
}

/// One segment is one remaining unit. No automatic rollover: only the provider can
/// confirm a new reset deadline. Missing/unreliable deadlines remain unknown.
public struct ResetCountdown:Codable,Equatable,Sendable {
 public var units:Int
 public var secondsPerUnit:Double
 public var nextReset:Date?
 public var isReliable:Bool
 public init(units:Int,secondsPerUnit:Double,nextReset:Date?=nil,isReliable:Bool=true){
  self.units=units;self.secondsPerUnit=secondsPerUnit;self.nextReset=nextReset;self.isReliable=isReliable
 }
 public func remainingUnits(at now:Date)->Int? {
  guard isReliable,(1...24).contains(units),secondsPerUnit.isFinite,secondsPerUnit>0,let nextReset else{return nil}
  let seconds=nextReset.timeIntervalSince(now)
  guard seconds.isFinite else{return nil}
  return min(units,max(0,Int(ceil(max(0,min(Double(units),seconds/secondsPerUnit))))))
 }
 public func value(at now:Date)->Double?{remainingUnits(at:now).map{Double($0)/Double(units)}}
}

