@available(macOS 26.0, *)
struct NativeResetArc:View {
 var name:String
 var value:Double?
 var spec:ResetArcCalibration
 var radius:CGFloat
 var size:CGFloat
 var center:CGPoint
 var stencil=false
 @Environment(\.accessibilityReduceMotion) private var reduceMotion
 @Environment(\.symbolInspectionScale) private var inspectionScale
 @Environment(\.symbolMotionDuration) private var motionDuration
 private var font:CGFloat{radius/spec.radius*100}
 var body:some View {
  NativeGaugePlacement(size:size,center:center,centerFromTop:spec.centerFromTop*font/100){
   ZStack {
    if !stencil {
     Image(name,variableValue:1).symbolVariableValueMode(.color)
      .opacity(size/inspectionScale<=24 ? 0.25:0.12)
    }
    Image(name,variableValue:stencil ? 1:value ?? 1)
     .symbolVariableValueMode(.color)
     .contentTransition(.symbolEffect(.automatic,options:.speed(0.3/max(0.01,motionDuration))))
   }
    .font(.system(size:font,weight:GaugeCalibration.Glyph.weights[Int(spec.weight)]))
    .imageScale(.small).symbolRenderingMode(stencil ? .monochrome:.hierarchical)
    .opacity(stencil || value != nil ? 1:0.45)
    .symbolEffectsRemoved(reduceMotion)
    .animation(reduceMotion ? nil:.smooth(duration:motionDuration),value:value)
  }
 }
}

/// Shared sector for both countdowns. The native assets use these same rays;
/// only their radii differ, so physical arc length is radius × sector angle.
struct ResetArcSector {
 var suffix:String
 var startDegrees:Double
 var endDegrees:Double{180-startDegrees}
 var spanRadians:Double{(endDegrees-startDegrees) * .pi/180}
 static func forSize(_ size:CGFloat)->Self {
  size<=18 ? Self(suffix:".micro",startDegrees:57):
   size<=24 ? Self(suffix:".compact",startDegrees:57):Self(suffix:"",startDegrees:56)
 }
}

@available(macOS 26.0, *)
struct NativeResetPair:View {
 var weekly:ResetCountdown
 var fiveHour:ResetCountdown
 var now:Date
 var size:CGFloat
 var weight:Font.Weight
 var stencil=false
 @Environment(\.gaugeCalibration) private var calibration
 @Environment(\.symbolInspectionScale) private var inspectionScale
 var body:some View {
  let pair=calibration.pair(size:size,weight:weight)
  let outerRadius=(pair.outer.diameter-pair.outer.stroke)/2
  let innerRadius=(pair.inner.diameter-pair.inner.stroke)/2
  let profile = size<=18 ? 18:size<=20 ? 20:size<=22 ? 22:size<=32 ? 32:48
  let outerName="compute.reset.\(weekly.units).p\(profile).outer"
  let innerName="compute.reset.\(fiveHour.units).p\(profile).inner"
  if let outer=ResetArcCalibration.all[outerName],let inner=ResetArcCalibration.all[innerName] {
   let wi=GaugeCalibration.Glyph.weights.firstIndex(of:weight) ?? 3
   // Paired custom masters carry the same physical stroke. No nearest-weight search.
   let selected=(outer[wi],inner[wi])
   let center=CGPoint(x:size/2*inspectionScale,y:size/2*inspectionScale)
   ZStack {
    NativeResetArc(name:outerName,value:weekly.value(at:now),spec:selected.0,radius:outerRadius*inspectionScale,size:size*inspectionScale,center:center,stencil:stencil)
    NativeResetArc(name:innerName,value:fiveHour.value(at:now),spec:selected.1,radius:innerRadius*inspectionScale,size:size*inspectionScale,center:center,stencil:stencil)
   }.frame(width:size*inspectionScale,height:size*inspectionScale)
  }
 }
}
